import random

class Solution:
    def sortReadings(self, readings: List[int]) -> List[int]:
        a = readings[:]
        def sort(lo, hi):
            if lo >= hi:
                return
            r = random.randint(lo, hi)
            a[r], a[hi] = a[hi], a[r]
            p, i = a[hi], lo
            for j in range(lo, hi):
                if a[j] < p:
                    a[i], a[j] = a[j], a[i]
                    i += 1
            a[i], a[hi] = a[hi], a[i]
            sort(lo, i - 1)
            sort(i + 1, hi)
        sort(0, len(a) - 1)
        return a

