class Solution {
    private final Random rng = new Random(7);
    private int[] a;

    public int[] sortReadings(int[] readings) {
        a = readings.clone();
        sort(0, a.length - 1);
        return a;
    }

    private void swap(int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

    private void sort(int lo, int hi) {
        if (lo >= hi) return;
        int p = a[lo + rng.nextInt(hi - lo + 1)];
        int lt = lo, i = lo, gt = hi;
        while (i <= gt) {
            if (a[i] < p) swap(lt++, i++);
            else if (a[i] > p) swap(i, gt--);
            else i++;
        }
        sort(lo, lt - 1);
        sort(gt + 1, hi);
    }
}

